/**
 * Kazuha pet — injected as a plain browser script by the Host half.
 *
 * It builds its own shadow root, so no app CSS can hide or move it and no app
 * element can sit above it: the sticker is a real draggable pet. A click opens a
 * small card with the DeepSeek balance (from /dsh-kazuha/balance.json) and a line.
 */
(function () {
  if (window.__dshKazuhaPetLoaded) return;
  window.__dshKazuhaPetLoaded = true;

  var STICKERS = [{"src": "data:image/webp;base64,", "name": "万叶嗨"}, {"src": "data:image/webp;base64,", "name": "万叶吃惊"}, {"src": "data:image/webp;base64,", "name": "万叶冒汗"}, {"src": "data:image/webp;base64,", "name": "万叶偷笑"}, {"src": "data:image/webp;base64,", "name": "万叶你可以的"}, {"src": "data:image/webp;base64,", "name": "万叶要晶核"}, {"src": "data:image/webp;base64,", "name": "万叶满意"}, {"src": "data:image/webp;base64,", "name": "万叶偶遇"}];
  var SIZE = 72;
  var POS_KEY = 'kazuha-pet:pos';
  var HINT_KEY = 'kazuha-pet:hint';
  var LINES = [
    '风起了，跟我走一段？',
    '一叶知秋，也知你累了。',
    '别急，风会把人送到该去的地方。',
    '红叶落尽，路还长呢。',
    '刀不必常出，心要常静。',
    '我在这儿听风，也在听你。',
    '先把这口气顺过来，再出刀。'
  ];
  var REASONS = {
    'no-account-service': '宿主还没加载余额接口，重启一次 DSH',
    'signed-out': '还没登录 DeepSeek 账号',
    'not-ready': '账号服务未就绪',
    'no-wallets': '账号里没有余额钱包',
    error: '余额读取失败',
    http: '余额接口未就绪（重启 DSH 后可用）',
    network: '连不上宿主'
  };

  var CSS = [
    ':host{all:initial}',
    '.wrap{position:relative;width:' + SIZE + 'px;height:' + SIZE + 'px;',
    '  font-family:"Songti SC","SimSun","Noto Sans SC","PingFang SC",system-ui,sans-serif}',
    '.pet{display:block;width:' + SIZE + 'px;height:' + SIZE + 'px;cursor:grab;',
    '  filter:drop-shadow(0 6px 10px rgba(0,0,0,.45));',
    '  animation:float 4.4s ease-in-out infinite;',
    '  -webkit-user-drag:none;user-select:none;-webkit-user-select:none;touch-action:none}',
    '.pet:active{cursor:grabbing}',
    '.pet:hover{filter:drop-shadow(0 8px 14px rgba(0,0,0,.5)) brightness(1.06)}',
    '@keyframes float{0%,100%{transform:translateY(0) rotate(-1.5deg)}50%{transform:translateY(-5px) rotate(1.5deg)}}',
    '.card{position:absolute;right:-4px;bottom:100%;margin-bottom:2px;width:206px;',
    '  padding:9px 11px 9px;border-radius:13px;background:#fffaf0;border:2.5px solid #33232c;',
    '  color:#3a2730;font-size:11.5px;line-height:1.5;box-shadow:0 12px 26px rgba(0,0,0,.42);',
    '  opacity:0;pointer-events:none;transform-origin:100% 100%;',
    '  transform:scale(.86) translateY(6px);transition:opacity .18s ease,transform .18s cubic-bezier(.3,1.4,.5,1)}',
    '.card.on{opacity:1;transform:scale(1) translateY(0)}',
    '.card:after{content:"";position:absolute;right:22px;bottom:-8px;width:11px;height:11px;',
    '  background:#fffaf0;border-right:2.5px solid #33232c;border-bottom:2.5px solid #33232c;',
    '  transform:rotate(45deg)}',
    '.card.flip{right:auto;left:-4px;transform-origin:0 100%}',
    '.card.flip:after{right:auto;left:22px}',
    '.card.below{bottom:auto;top:100%;margin-bottom:0;margin-top:2px}',
    '.card.below:after{bottom:auto;top:-8px;transform:rotate(225deg)}',
    '.head{display:flex;align-items:center;gap:5px;font-size:10.5px;color:#8a6b58;letter-spacing:.06em}',
    '.dot{width:6px;height:6px;border-radius:50%;background:#8fbf9a}',
    '.dot.off{background:#c98b6b}',
    '.money{font:700 20px/1.25 "Optima","Palatino Linotype","Times New Roman",serif;color:#8f1f1f}',
    '.sub{font-size:10.5px;color:#8a6b58}',
    '.line{margin-top:6px;padding-top:6px;border-top:1px dashed rgba(90,43,31,.28);',
    '  font-size:12px;color:#5a2b1f;line-height:1.5}',
    '.hint{position:absolute;right:0;bottom:100%;margin-bottom:4px;padding:5px 9px;border-radius:9px;',
    '  white-space:nowrap;background:rgba(51,35,44,.92);color:#ffeccb;',
    '  border:1.5px solid rgba(255,226,180,.5);font-size:11px;pointer-events:none;',
    '  opacity:0;transition:opacity .3s ease}',
    '.hint.on{opacity:1}'
  ].join('');

  function clamp(n, lo, hi) {
    return Math.min(Math.max(n, lo), hi);
  }

  function readPos() {
    try {
      var raw = localStorage.getItem(POS_KEY);
      if (!raw) return null;
      var p = JSON.parse(raw);
      if (p && typeof p.x === 'number' && typeof p.y === 'number') return p;
    } catch (e) {}
    return null;
  }

  function mount() {
    if (!document.body) {
      setTimeout(mount, 50);
      return;
    }
    if (document.getElementById('dsh-kazuha-pet')) return;

    var host = document.createElement('div');
    host.id = 'dsh-kazuha-pet';
    host.style.cssText =
      'position:fixed;z-index:2147483000;width:' + SIZE + 'px;height:' + SIZE + 'px;' +
      'right:24px;bottom:96px;pointer-events:auto;';

    var root = host.attachShadow ? host.attachShadow({ mode: 'open' }) : host;
    root.innerHTML =
      '<style>' + CSS + '</style>' +
      '<div class="wrap">' +
      '<div class="card"><div class="head"><span class="dot"></span>DeepSeek 余额</div>' +
      '<div class="money">—</div><div class="sub"></div><div class="line"></div></div>' +
      '<div class="hint">拖动我 · 点一下看余额</div>' +
      '<img class="pet" alt="" draggable="false">' +
      '</div>';

    document.body.appendChild(host);

    var wrap = root.querySelector('.wrap');
    var img = root.querySelector('.pet');
    var card = root.querySelector('.card');
    var dot = root.querySelector('.dot');
    var money = root.querySelector('.money');
    var sub = root.querySelector('.sub');
    var line = root.querySelector('.line');
    var hint = root.querySelector('.hint');

    var idx = Math.floor(Math.random() * STICKERS.length);
    var balance = null;
    var balanceAt = 0;
    var cardTimer = 0;
    var drag = null;

    function paintSticker() {
      var s = STICKERS[idx];
      img.src = s.src;
      img.alt = s.name;
      img.title = '枫原万叶 · ' + s.name;
    }

    function paintCard() {
      dot.className = 'dot';
      if (balance && balance.ok) {
        money.textContent = (balance.currency === 'USD' ? '$' : '¥') + balance.total;
        var t = new Date(balance.at);
        sub.textContent = '赠金 ' + (balance.currency === 'USD' ? '$' : '¥') + balance.bonus +
          ' · ' + ('0' + t.getHours()).slice(-2) + ':' + ('0' + t.getMinutes()).slice(-2);
      } else if (balance) {
        dot.className = 'dot off';
        money.textContent = '—';
        sub.textContent = REASONS[balance.reason] || REASONS.error;
      } else {
        money.textContent = '—';
        sub.textContent = '读取中…';
      }
    }

    function loadBalance() {
      paintCard();
      fetch('/dsh-kazuha/balance.json', { credentials: 'same-origin', cache: 'no-store' })
        .then(function (r) {
          if (!r.ok) return { ok: false, reason: 'http' };
          return r.json();
        })
        .then(function (body) {
          balance = body && typeof body === 'object' ? body : { ok: false, reason: 'error' };
          balanceAt = Date.now();
          paintCard();
        })
        .catch(function () {
          balance = { ok: false, reason: 'network' };
          paintCard();
        });
    }

    function placeCard() {
      var rect = host.getBoundingClientRect();
      var cw = card.offsetWidth;
      var ch = card.offsetHeight;
      var spaceLeft = rect.left;
      var spaceRight = window.innerWidth - (rect.left + SIZE);
      if (spaceLeft < cw + 10 && spaceRight > spaceLeft) card.classList.add('flip');
      else card.classList.remove('flip');
      if (rect.top < ch + 10) card.classList.add('below');
      else card.classList.remove('below');
    }

    function openCard() {
      idx = (idx + 1 + Math.floor(Math.random() * (STICKERS.length - 1))) % STICKERS.length;
      paintSticker();
      line.textContent = '「' + LINES[Math.floor(Math.random() * LINES.length)] + '」';
      placeCard();
      card.classList.add('on');
      paintCard();
      if (!balance || Date.now() - balanceAt > 60000) loadBalance();
      clearTimeout(cardTimer);
      cardTimer = setTimeout(function () {
        card.classList.remove('on');
      }, 9000);
    }

    function savePos() {
      try {
        localStorage.setItem(POS_KEY, JSON.stringify({
          x: parseInt(host.style.left, 10),
          y: parseInt(host.style.top, 10)
        }));
      } catch (e) {}
    }

    function place(x, y) {
      host.style.left = clamp(x, 0, Math.max(0, window.innerWidth - SIZE)) + 'px';
      host.style.top = clamp(y, 0, Math.max(0, window.innerHeight - SIZE)) + 'px';
      host.style.right = 'auto';
      host.style.bottom = 'auto';
    }

    img.addEventListener('pointerdown', function (e) {
      if (e.button !== 0) return;
      e.preventDefault();
      var rect = host.getBoundingClientRect();
      drag = { sx: e.clientX, sy: e.clientY, x0: rect.left, y0: rect.top, moved: false };
      if (img.setPointerCapture) {
        try { img.setPointerCapture(e.pointerId); } catch (err) {}
      }
    });

    img.addEventListener('pointermove', function (e) {
      if (!drag) return;
      var dx = e.clientX - drag.sx;
      var dy = e.clientY - drag.sy;
      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) drag.moved = true;
      if (drag.moved) place(drag.x0 + dx, drag.y0 + dy);
    });

    function endDrag() {
      if (!drag) return;
      var moved = drag.moved;
      drag = null;
      if (moved) savePos();
      else openCard();
    }

    img.addEventListener('pointerup', endDrag);
    img.addEventListener('pointercancel', endDrag);
    img.addEventListener('click', function (e) { e.preventDefault(); });

    var stored = readPos();
    if (stored) place(stored.x, stored.y);

    window.addEventListener('resize', function () {
      var rect = host.getBoundingClientRect();
      if (host.style.left) place(rect.left, rect.top);
      if (card.classList.contains('on')) placeCard();
    });

    paintSticker();
    paintCard();

    var seen = false;
    try { seen = localStorage.getItem(HINT_KEY) === '1'; } catch (e) { seen = true; }
    if (!seen) {
      hint.classList.add('on');
      setTimeout(function () {
        hint.classList.remove('on');
        try { localStorage.setItem(HINT_KEY, '1'); } catch (e) {}
      }, 5200);
    }

    window.__dshKazuhaPet = {
      open: openCard,
      refresh: loadBalance,
      remove: function () {
        host.remove();
        window.__dshKazuhaPetLoaded = false;
      }
    };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mount);
  } else {
    mount();
  }
})();
